 if((env.ADMIN_UIDS||'').split(',').map(s=>s.trim()).includes(data.uid))return Response.json({allowed:true,unlimited:true});
 if(env.AI_ABUSE_ENABLED!=='true')return Response.json({allowed:true,disabled:true});
